import {revise} from '/engine.js';
const $=s=>document.querySelector(s),scope=location.pathname.replace(/\/$/,'');
let view,exposed=false,submitted=false,dwell=0,lastTime=0,inView=false;
const api=async(action,input)=>{const r=await fetch(`${scope}/api/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request unavailable');return j;};
function node(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
function sentence(c,original){const value=original?c.original_display:c.current_display;return c.sentence.replace('{value}',value.replace(/\B(?=(\d{3})+(?!\d))/g,','));}
function allFacts(container,payload){
 for(const c of payload.claims){const p=node('p',sentence(c,false));p.append(node('span',`Previously: ${sentence(c,true)}`,'context'));container.append(p);}
}
function render(view){
 const {facts,renderer}=view,box=$('#explanation');box.replaceChildren();
 $('#experience-name').textContent=renderer==='correction_note'?'CORRECTION NOTE':'EVIDENCE TIME MACHINE';
 $('#assignment').textContent=`Assigned by Flagsmith · ${view.provider_variant||'current value'}`;
 $('#notice').textContent=`${view.environment||'Development'} · ${view.mode==='aa'?'A/A calibration: both arms show identical Correction Notes.':'Correction Fork'} · Historical source revision replay`;
 if(renderer==='correction_note'){
  const wrap=node('section',undefined,'correction-note');wrap.append(node('h2','Correction · 22 May 2026'));
  wrap.append(node('p','The ONS corrected its corporations’ gross operating surplus series. The figures below compare the original release with the corrected release. Total GDP was not affected.','evidence-note'));
  const prose=node('div',undefined,'claim-prose');allFacts(prose,facts);wrap.append(prose);box.append(wrap);
 }else{
  const machine=node('section',undefined,'time-machine');
  const head=node('div',undefined,'machine-head');head.append(node('strong','EVIDENCE TIME MACHINE'),node('span','ONE SOURCE · TWO RELEASES'));machine.append(head);
  const timeline=node('div',undefined,'timeline');const old=node('button','14 May · Original'),current=node('button','22 May · Corrected');old.type=current.type='button';timeline.append(old,current);machine.append(timeline);
  const release=node('div',undefined,'release-label'),packet=node('div',undefined,'source-packet'),prose=node('div',undefined,'claim-prose');prose.setAttribute('aria-live','polite');machine.append(release,packet,prose);
  let selected=facts.claims[0].id,original=false;
  function show(isOriginal){original=isOriginal;old.setAttribute('aria-pressed',String(original));current.setAttribute('aria-pressed',String(!original));machine.dataset.vintage=original?'original':'corrected';release.textContent=original?'THE ORIGINAL SOURCE IS UNDER THE ARTICLE':'THE CORRECTED SOURCE IS UNDER THE ARTICLE';prose.replaceChildren();packet.replaceChildren();
   const source=facts.sources[original?0:1],focus=facts.claims.find(c=>c.id===selected);
   packet.append(node('strong',`ONS SOURCE SHEET · ${source.released_at}`));
   const inputs=node('div',undefined,'source-inputs');for(const key of focus.dependencies){const o=source.observations[key];const item=node('div');item.append(node('span',o.period),node('b',Number(o.value).toLocaleString('en-GB')+(o.unit==='percent'?'%':' £m')));inputs.append(item);}packet.append(inputs,node('span','These are the inputs to the selected sentence.','caption'));
   // Source movement executes the very same generic engine used by the backend.
   const recomputed=revise(facts.claims,facts.sources[0],source);
   for(const c of recomputed){const card=node('section',undefined,'temporal-claim');card.dataset.selected=String(c.id===selected);const p=node('p');const [prefix,suffix]=c.sentence.split('{value}');p.append(document.createTextNode(prefix),node('mark',c.current_display.replace(/\B(?=(\d{3})+(?!\d))/g,',')),document.createTextNode(suffix));card.append(p);
    const canonical=facts.claims.find(x=>x.id===c.id);
    card.append(node('span',`Original: ${canonical.original_display} · Corrected: ${canonical.current_display}`,'transition'));
    const trace=node('button',c.id===selected?'Source shown above':'Trace this sentence','trace-sentence');trace.type='button';trace.setAttribute('aria-pressed',String(c.id===selected));trace.addEventListener('click',()=>{if(selected===c.id)return;selected=c.id;show(original);machine.querySelector('.trace-sentence[aria-pressed="true"]').focus({preventScroll:true});});card.append(trace);prose.append(card);
   }
  }
  old.addEventListener('click',()=>show(true));current.addEventListener('click',()=>show(false));
  const rewind=node('button','Hold to lay the original source under the article','rewind-button');rewind.type='button';
  const restore=()=>show(false);rewind.addEventListener('pointerdown',e=>{rewind.setPointerCapture(e.pointerId);show(true);});rewind.addEventListener('pointerup',restore);rewind.addEventListener('pointercancel',restore);rewind.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();show(true);}});rewind.addEventListener('keyup',e=>{if(e.code==='Space')restore();});rewind.addEventListener('blur',restore);
  const top=node('div',undefined,'rewind-tray');top.append(rewind,node('span','Release to return to the correction. Keyboard: hold Space.','caption'));machine.insertBefore(top,release);show(false);
  const bottom=node('div',undefined,'baseline-facts');bottom.append(node('p','Move the source. The sentences recompute. Historical wording stays attached to the release that supported it.'));machine.append(bottom);box.append(machine);
 }
 box.append(node('p','Figures from ONS Table 3 are compared as published in £ millions. The annual comparison is rounded to one decimal place. Real GDP is a separate measure.','evidence-note'));
 $('#proof-content').replaceChildren();
 for(const s of facts.sources){const p=node('p');const a=node('a',`${s.id} · ${s.released_at}`);a.href=s.url;a.target='_blank';a.rel='noopener';p.append(a,node('br'),node('span',s.literal_unit_note),node('br'),node('code',`Captured bytes SHA256: ${s.sha256}`));for(const o of Object.values(s.observations))p.append(node('br'),node('span',`${o.period}: ${o.value} ${o.unit}. ${o.basis}`));$('#proof-content').append(p);}
 for(const c of facts.claims)$('#proof-content').append(node('p',`${c.label}: ${c.original_display} to ${c.current_display}; ${c.state.replaceAll('_',' ')}. Exact calculation: ${c.current_value.numerator} / ${c.current_value.denominator}.`));
 $('#proof-content').append(node('p',facts.sources[1].semantic_limit),node('code',`Correction payload SHA256: ${view.correction_payload_hash}`));
}
$('#begin').addEventListener('click',async()=>{
 $('#begin').disabled=true;$('#error').textContent='';
 try{
  view=await api('consent',{consent:true,adultEnglish:$('#adult-english').checked,firstTime:$('#first-time').checked});render(view);$('#consent').hidden=true;$('#experience').hidden=false;
  if(view.study_complete){$('#check').hidden=true;$('#reevaluate').hidden=true;$('#exposure-status').textContent='Canonical correction. This reading is outside the closed study.';$('#notice').textContent=`${view.environment} · Canonical experience from Flagsmith · Study completed`;return;}
  $('#question').textContent=view.protocol.question;$('#question-order').textContent=view.protocol.order.join(' / ');
  for(const [i,values]of view.protocol.options.entries()){const label=node('label'),input=document.createElement('input');input.type='radio';input.name='answer';input.value=String(i);input.required=true;label.append(input,node('span',typeof values==='string'?values:values.join(' / ')));$('#options').append(label);}
  const observer=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting&&entries[0].intersectionRatio>=.5;},{threshold:[0,.5,1]});
  const observeFirstClaim=()=>{observer.disconnect();inView=false;const first=$('#explanation .claim-prose p');if(first)observer.observe(first);};
  observeFirstClaim();new MutationObserver(observeFirstClaim).observe($('#explanation'),{childList:true,subtree:true});
  // Accumulate only visible time; a hidden or offscreen reader does not expose.
  function tick(now){if(exposed||submitted)return;if(lastTime&&document.visibilityState==='visible'&&inView)dwell+=Math.min(now-lastTime,100);lastTime=now;
   if(dwell>=view.protocol.exposure_dwell_ms){api('exposure',{payloadHash:view.correction_payload_hash,visible:true,dwellMs:Math.floor(dwell)}).then(()=>{exposed=true;$('#submit').disabled=false;$('#exposure-status').textContent='Correction read. Your first response will be recorded.';}).catch(e=>{$('#error').textContent=e.message;dwell=0;requestAnimationFrame(tick);});return;}requestAnimationFrame(tick);
  }requestAnimationFrame(tick);
  window.parent.postMessage({type:'proofpivot-assigned',value:view.renderer,variant:view.provider_variant,experiment_id:view.experiment_id},location.origin);
 }catch(e){$('#error').textContent=e.message;$('#begin').disabled=false;}
});
$('#check').addEventListener('submit',async e=>{
 e.preventDefault();if(!exposed||submitted)return;
 const choice=$('input[name=answer]:checked');if(!choice)return;$('#submit').disabled=true;
 try{await api('answer',{option:Number(choice.value),payloadHash:view.correction_payload_hash});submitted=true;$('#answer-status').textContent='Thank you. Your first complete answer is saved. Later attempts cannot change it.';$('#options').disabled=true;$('#submit').textContent='First response saved';}
 catch(err){$('#error').textContent=err.message;$('#submit').disabled=false;}
});
$('#reevaluate').addEventListener('click',async()=>{try{const fresh=await api('reevaluate',{});render({...view,...fresh});$('#error').textContent='';window.parent.postMessage({type:'proofpivot-reevaluated',value:fresh.renderer,variant:fresh.provider_variant,experiment:fresh.experiment??null},location.origin);}catch(e){$('#error').textContent=e.message;}});
fetch('/api/state').then(r=>r.json()).then(s=>{$('#notice').textContent=`${s.environment} · ${s.mode==='aa'?'A/A calibration · Identical Correction Notes':'Correction Fork'}`;if(s.environment==='Production'){$('#eligibility').hidden=false;$('#participation-kind').textContent=s.study_role==='pilot'?'Human pilot. These responses are excluded from the later main study.':'Independent reading study. Your first complete answer is recorded once.';}}).catch(()=>{$('#notice').textContent='Experiment unavailable';});

